import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { root, runTool } from './tools.mjs';

mkdirSync(join(root, '.tmp'), { recursive: true });
const output = join(root, '.tmp/rust-licenses.json');
runTool('cargo-about', [
  'generate',
  '--locked',
  '--fail',
  '--manifest-path',
  'src-tauri/Cargo.toml',
  '--config',
  'about.toml',
  '--format',
  'json',
  '--output-file',
  output,
]);
const report = JSON.parse(readFileSync(output, 'utf8'));
const lines = [
  '# Rust dependency notices',
  '',
  'Generated by cargo-about from Cargo.lock for Windows x64, macOS Intel/Apple Silicon and Linux x64. Includes build and transitive dependencies. License selections and supplied copyright notices follow.',
  '',
];
for (const license of report.licenses) {
  lines.push(`## ${license.name}`, '', 'Used by:', '');
  for (const used of license.used_by) {
    const pkg = used.crate;
    const source =
      pkg.name === 'glib' && pkg.version === '0.18.5+emdeck.1'
        ? 'https://github.com/Erdos-Miller/emdeck/tree/main/src-tauri/vendor/glib'
        : `https://crates.io/crates/${pkg.name}/${pkg.version}`;
    lines.push(`- ${pkg.name} ${pkg.version} — ${source}`);
  }
  lines.push(
    '',
    '````text',
    license.text
      .replaceAll('\r\n', '\n')
      .replace(/[\t ]+$/gm, '')
      .trim(),
    '````',
    ''
  );
}
mkdirSync(join(root, 'docs/licenses'), { recursive: true });
writeFileSync(join(root, 'docs/licenses/RUST.md'), `${lines.join('\n').trimEnd()}\n`);
console.log(`Recorded ${report.licenses.length} Rust license texts.`);
